SELECT o.*, h.id as h_id, h.name as h_name, h.address as h_address, h.image_url as h_image_url, h.owner_id as h_owner_id FROM `order` o LEFT JOIN homestay h ON o.homestay_id = h.id WHERE h.owner_id = #{landlordId}
AND o.status = #{status}
AND h.name LIKE CONCAT('%', #{homestayName}, '%')
AND o.check_in_date >= #{startDate} AND o.check_out_date <= #{endDate}
ORDER BY
o.price o.check_in_date o.create_time
DESC
ASC
ORDER BY o.create_time DESC
LIMIT #{start}, #{pageSize}

SELECT COUNT(*)
FROM `order` o
LEFT JOIN homestay h ON o.homestay_id = h.id
WHERE h.owner_id = #{landlordId}

    AND o.status = #{status}


    AND h.name LIKE CONCAT('%', #{homestayName}, '%')


    AND o.check_in_date >= #{startDate} AND o.check_out_date <= #{endDate}

SELECT o.*, h.id as h_id, h.name as h_name, h.address as h_address, h.image_url as h_image_url, h.owner_id as h_owner_id, e.id as e_id, e.name as e_name, e.location as e_location, e.image_url as e_image_url, u.id as u_id, u.username as u_username, u.phone as u_phone, u.email as u_email, u.name as u_name FROM `order` o LEFT JOIN homestay h ON o.homestay_id = h.id LEFT JOIN experience e ON o.experience_id = e.id LEFT JOIN user u ON o.user_id = u.id
o.status = #{status}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.create_time DESC LIMIT #{start}, #{pageSize}

